// Status and recommended tasks per VM. Same rules as the IT Infrastructure Space (a test keeps both equal).
function assess(vm, rules) {
  const reasons = [];
  const add = (level, text, key) => reasons.push({ level, text, key });
  if (!vm.reachable) add('red', 'Not reachable: the VM does not answer monitoring checks', 'unreachable');
  else {
    const metric = (field, label, unit, key) => {
      const v = vm[field], r = rules[field];
      if (v === null || v === undefined) return;
      if (r.appliesTo && r.appliesTo !== vm.env) return;
      if (field === 'certExpiresInDays') {
        if (v <= r.red) add('red', `${label} ${v}${unit} (red up to ${r.red}${unit})`, key);
        else if (v <= r.yellow) add('yellow', `${label} ${v}${unit} (yellow up to ${r.yellow}${unit})`, key);
      } else if (v >= r.red) add('red', `${label} ${v}${unit} (red from ${r.red}${unit})`, key);
      else if (v >= r.yellow) add('yellow', `${label} ${v}${unit} (yellow from ${r.yellow}${unit})`, key);
    };
    metric('cpuPct', 'CPU', ' %', 'cpu'); metric('memPct', 'Memory', ' %', 'mem'); metric('diskPct', 'Disk', ' %', 'disk');
    metric('backupAgeHours', 'Last backup', ' h ago', 'backup'); metric('patchLagDays', 'Security patch missing for', ' days', 'patch');
    metric('certExpiresInDays', 'TLS certificate expires in', ' days', 'cert');
  }
  const status = reasons.some((r) => r.level === 'red') ? 'red' : reasons.length ? 'yellow' : 'green';
  reasons.sort((a, b) => (a.level === b.level ? 0 : a.level === 'red' ? -1 : 1));
  return { status, reasons };
}
function tasksFor(vm, reasons, defs) {
  return reasons.map((r) => ({ vm: vm.name, key: r.key, title: defs[r.key].title, steps: defs[r.key].steps, reboot: defs[r.key].reboot, approver: defs[r.key].approver, urgency: r.level === 'red' ? 'urgent' : 'planned', because: r.text }));
}
function plan(vms, rules, defs) {
  return vms.map((vm) => ({ vm, ...assess(vm, rules) })).filter((x) => x.reasons.length).map((x) => {
    const tasks = tasksFor(x.vm, x.reasons, defs);
    return { vm: x.vm.name, status: x.status, tasks, window: tasks.some((t) => t.reboot) ? 'Maintenance window needed (restart)' : 'Can run during operations', bundle: tasks.length > 1 };
  }).sort((a, b) => (a.status === b.status ? a.vm.localeCompare(b.vm) : a.status === 'red' ? -1 : 1));
}

