const out = [];
for (const item of $input.all()) {
  const vm = item.json;
  const a = assess(vm, RULES);
  const tasks = tasksFor(vm, a.reasons, TASKS);
  out.push({ json: { vm: vm.name, status: a.status, tasks, taskCount: tasks.length } });
}
return out;

// Maintenance plan: urgent tasks first, one maintenance window per VM when a task needs a restart. Ends in "proposal only": a person approves, nothing runs.
const items = $input.all().map((i) => i.json);
const has = items.filter((i) => i.taskCount > 0);
const plan = has.map((x) => ({ vm: x.vm, status: x.status, tasks: x.tasks, window: x.tasks.some((t) => t.reboot) ? 'Maintenance window needed (restart)' : 'Can run during operations', bundle: x.tasks.length > 1 }))
  .sort((a, b) => (a.status === b.status ? a.vm.localeCompare(b.vm) : a.status === 'red' ? -1 : 1));
const urgent = plan.reduce((n, p) => n + p.tasks.filter((t) => t.urgency === 'urgent').length, 0);
const total = plan.reduce((n, p) => n + p.tasks.length, 0);
const lines = plan.flatMap((p) => [`${p.vm} (${p.status}) - ${p.window}${p.bundle ? ', tasks bundled in one window' : ''}`, ...p.tasks.map((t) => `  - [${t.urgency}] ${t.title} (approver: ${t.approver}) because ${t.because}`)]);
const text = [`VM maintenance plan, ${items.length} VMs, ${total} tasks (${urgent} urgent) on ${plan.length} VMs`, ...lines, 'Proposal only. Nothing was run, restarted or changed. The named approver decides.'].join('\n');
return [{ json: { counts: { vms: items.length, withTasks: plan.length, tasks: total, urgent }, plan, digest: text } }];
